class Gasto:
    def __init__(self, descripcion, categoria, valor):
        self.descripcion = descripcion
        self.categoria = categoria
        self.valor = valor

    def con_iva(self):
        return round(self.valor * 1.13)

    def es_grande(self, limite=20000):
        return self.valor > limite

    def __str__(self):
        return f"{self.descripcion} ({self.categoria}): ₡{self.valor:,}"

    def __repr__(self):
        return f"Gasto({self.descripcion!r}, {self.categoria!r}, {self.valor})"

g = Gasto("Zapatos", "ropa", 35000)
print(g.con_iva())      # 39550
print(g.es_grande())    # True
print(g)                # Zapatos (ropa): ₡35,000
print([g])              # [Gasto('Zapatos', 'ropa', 35000)]

class Presupuesto:
    def __init__(self, saldo):
        self._saldo = 0
        self.saldo = saldo      # pasa por el setter: se valida

    @property
    def saldo(self):
        return self._saldo

    @saldo.setter
    def saldo(self, nuevo):
        if nuevo < 0:
            raise ValueError("el saldo no puede ser negativo")
        self._saldo = nuevo

p = Presupuesto(150000)
print(p.saldo)          # 150000
p.saldo = 120000
print(p.saldo)          # 120000
try:
    p.saldo = -5000
except ValueError as e:
    print("Error:", e)  # Error: el saldo no puede ser negativo

