class Presupuesto:
    creados = 0                      # atributo de clase: compartido

    def __init__(self, nombre):
        self.nombre = nombre
        self.gastos = []             # composición: una lista de Gasto
        Presupuesto.creados += 1

    def agregar(self, gasto):
        self.gastos.append(gasto)

    def total(self):
        return sum(g.valor for g in self.gastos)

    @classmethod
    def desde_lista(cls, nombre, pares):
        p = cls(nombre)
        for descripcion, valor in pares:
            p.agregar(Gasto(descripcion, valor))
        return p

octubre = Presupuesto.desde_lista("octubre", [("casado", 4500), ("bus", 600)])
noviembre = Presupuesto("noviembre")
print(octubre.total())                              # 5100
print(len(octubre.gastos), len(noviembre.gastos))   # 2 0
print(Presupuesto.creados)                          # 2

class Vehiculo:
    def __init__(self, placa, tarifa_hora):
        self.placa = placa
        self.tarifa_hora = tarifa_hora

    def cobrar(self, horas):
        return self.tarifa_hora * horas

    def __str__(self):
        return f"{type(self).__name__} {self.placa}"

class Carro(Vehiculo):
    def __init__(self, placa):
        super().__init__(placa, 1000)

class Moto(Vehiculo):
    def __init__(self, placa):
        super().__init__(placa, 500)

    def cobrar(self, horas):
        # las motos pagan máximo 2000 al día
        return min(super().cobrar(horas), 2000)

c = Carro("BCD123")
m = Moto("MOT456")
print(c, c.cobrar(3))                                # Carro BCD123 3000
print(m, m.cobrar(6))                                # Moto MOT456 2000
print(isinstance(m, Vehiculo), isinstance(c, Moto))  # True False

from abc import ABC, abstractmethod
import math

class Figura(ABC):
    @abstractmethod
    def area(self):
        ...

class Cuadrado(Figura):
    def __init__(self, lado):
        self.lado = lado
    def area(self):
        return self.lado ** 2

class Circulo(Figura):
    def __init__(self, radio):
        self.radio = radio
    def area(self):
        return math.pi * self.radio ** 2

figuras = [Cuadrado(3), Circulo(1), Cuadrado(2)]
for f in figuras:
    print(type(f).__name__, round(f.area(), 2))
# Cuadrado 9
# Circulo 3.14
# Cuadrado 4
print(round(sum(f.area() for f in figuras), 2))   # 16.14
